import math


def evaluate(expr: str) -> int:
    if not isinstance(expr, str) or not expr.strip():
        raise ValueError("Empty expression")

    # 1. Tokenize into raw tokens
    raw_tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            raw_tokens.append(("NUM", int(expr[i:j])))
            i = j
        elif c in "+-*/%^!()":
            raw_tokens.append((c, c))
            i += 1
        else:
            raise ValueError(f"Invalid character: {c}")

    if not raw_tokens:
        raise ValueError("Empty expression")

    # 2. Validate token adjacencies and insert implicit multiplication
    tokens = []
    for t in raw_tokens:
        if tokens:
            prev = tokens[-1]
            # A number following a number, closing parenthesis, or '!' is malformed
            if t[0] == "NUM" and prev[0] in ("NUM", ")", "!"):
                raise ValueError(f"Malformed expression: number following {prev[0]}")
            # An opening parenthesis following a number, closing parenthesis, or '!' implies multiplication
            if t[0] == "(" and prev[0] in ("NUM", ")", "!"):
                tokens.append(("*", "*"))
        tokens.append(t)

    # 3. Arithmetic helper functions
    def trunc_div(a: int, b: int) -> int:
        if b == 0:
            raise ValueError("Division by zero")
        q = abs(a) // abs(b)
        return -q if (a < 0) ^ (b < 0) else q

    def trunc_mod(a: int, b: int) -> int:
        if b == 0:
            raise ValueError("Remainder by zero")
        q = trunc_div(a, b)
        return a - q * b

    def calc_pow(base: int, exp: int) -> int:
        if exp < 0:
            raise ValueError("Negative exponent")
        return base**exp

    def calc_fact(val: int) -> int:
        if val < 0:
            raise ValueError("Factorial of negative number")
        return math.factorial(val)

    # 4. Recursive descent parser
    pos = 0

    def peek():
        if pos < len(tokens):
            return tokens[pos][0]
        return None

    def consume(expected=None):
        nonlocal pos
        if pos >= len(tokens):
            raise ValueError("Unexpected end of expression")
        tok = tokens[pos]
        if expected is not None and tok[0] != expected:
            raise ValueError(f"Expected {expected}, got {tok[0]}")
        pos += 1
        return tok

    def parse_expr():
        # Precedence 1: binary + and - (left-associative)
        node = parse_term()
        while peek() in ("+", "-"):
            op = consume()[0]
            right = parse_term()
            if op == "+":
                node = node + right
            else:
                node = node - right
        return node

    def parse_term():
        # Precedence 2: binary *, /, % (left-associative)
        node = parse_unary()
        while peek() in ("*", "/", "%"):
            op = consume()[0]
            right = parse_unary()
            if op == "*":
                node = node * right
            elif op == "/":
                node = trunc_div(node, right)
            elif op == "%":
                node = trunc_mod(node, right)
        return node

    def parse_unary():
        # Precedence 3: unary minus (may be repeated)
        if peek() == "-":
            consume("-")
            return -parse_unary()
        return parse_power()

    def parse_power():
        # Precedence 4: power ^ (right-associative, binds tighter than unary minus)
        base = parse_postfix()
        if peek() == "^":
            consume("^")
            exp = parse_unary()
            return calc_pow(base, exp)
        return base

    def parse_postfix():
        # Precedence 5: postfix factorial ! (binds tightest)
        node = parse_primary()
        while peek() == "!":
            consume("!")
            node = calc_fact(node)
        return node

    def parse_primary():
        tok = peek()
        if tok == "NUM":
            return consume("NUM")[1]
        elif tok == "(":
            consume("(")
            val = parse_expr()
            consume(")")
            return val
        elif tok is None:
            raise ValueError("Unexpected end of expression")
        else:
            raise ValueError(f"Unexpected token: {tok}")

    result = parse_expr()
    if pos < len(tokens):
        raise ValueError(f"Unexpected token: {tokens[pos][0]}")

    return result
